code.cpp:
class Solution {
public:
    int maxDistance(vector<int>& position, int m) {
        sort(position.begin(), position.end());
        int n = position.size();
        int lo = 1, hi = position[n - 1] - position[0];
        int ans = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int count = 1;
            int last = position[0];
            for (int i = 1; i < n; i++) {
                if (position[i] - last >= mid) {
                    count++;
                    last = position[i];
                }
            }
            if (count >= m) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
};
